"""Scratch author control for the projection contract."""
import copy
import threading

class Projection:
    def __init__(self, state=None):
        self._lock = threading.Lock()
        state = copy.deepcopy(state or {})
        self._rows = state.get("rows", {})
        self._boundary = state.get("boundary", -1)
        self._live = state.get("live", {})

    def install_snapshot(self, rows, at_sequence, before_publish=None):
        snapshot = dict(rows)
        if before_publish is not None:
            before_publish()
        with self._lock:
            if at_sequence < self._boundary:
                return
            self._live = {key: event for key, event in self._live.items() if event["sequence"] > at_sequence}
            for key, event in self._live.items():
                if event["kind"] == "delete":
                    snapshot.pop(key, None)
                else:
                    snapshot[key] = event["value"]
            self._rows = snapshot
            self._boundary = at_sequence

    def apply(self, event):
        event = dict(event)
        with self._lock:
            prior = self._live.get(event["key"])
            if event["sequence"] <= self._boundary or (prior is not None and event["sequence"] <= prior["sequence"]):
                return
            self._live[event["key"]] = event
            if event["kind"] == "delete":
                self._rows.pop(event["key"], None)
            else:
                self._rows[event["key"]] = event["value"]

    def view(self):
        with self._lock:
            return dict(self._rows)

    def dump_state(self):
        with self._lock:
            return copy.deepcopy({"rows": self._rows, "boundary": self._boundary, "live": self._live})
